### Step 2: Implement ConstraintResolver

Core struct with cached resolution. Key types:

```rust
// src/constraints/resolver.rs

use std::collections::HashMap;
use glob::{MatchOptions, Pattern};
use tracing::warn;
use crate::db::Db;
use crate::error::{Result, SutraError};
use crate::rules::{Constraint, ConstraintKind};

struct ResolvedCache {
    pairs: Vec<(i64, i64)>,
    membership_generation: Option<String>, // clustered_at from clustering_meta_full
}

pub struct ConstraintResolver {
    cache: Option<ResolvedCache>,
}

impl ConstraintResolver {
    pub fn new() -> Self {
        Self { cache: None }
    }

    pub fn resolve(
        &mut self,
        constraints: &[Constraint],
        db: &Db,
        path_map: &HashMap<i64, String>,
    ) -> Result<Vec<(i64, i64)>> {
        // 1. Check generation — clustered_at timestamp from clustering_meta_full
        let current_gen = db.clustering_meta_full()?
            .map(|(_, _, clustered_at)| clustered_at);

        if let Some(ref cache) = self.cache {
            if cache.membership_generation == current_gen {
                return Ok(cache.pairs.clone());
            }
        }

        // 2. Resolve all constraints to file-level pairs
        let components = db.all_components()?;
        let mut file_ids_cache: HashMap<String, Vec<i64>> = HashMap::new();
        let mut pairs = Vec::new();

        let glob_opts = MatchOptions {
            require_literal_separator: true,
            ..MatchOptions::default()
        };

        for constraint in constraints {
            match &constraint.kind {
                ConstraintKind::Boundary { from_component, to_component } => {
                    let from_cid = find_component(&components, from_component);
                    let to_cid = find_component(&components, to_component);
                    let (Some(from_cid), Some(to_cid)) = (from_cid, to_cid) else {
                        warn!(
                            constraint_id = %constraint.id,
                            from = %from_component,
                            to = %to_component,
                            "skipping boundary constraint: component not found"
                        );
                        continue;
                    };
                    // Cache file_ids per component to avoid repeated queries
                    let from_files = file_ids_cache.entry(from_cid.clone())
                        .or_insert_with(|| db.component_file_ids(&from_cid).unwrap_or_default())
                        .clone();
                    let to_files = file_ids_cache.entry(to_cid.clone())
                        .or_insert_with(|| db.component_file_ids(&to_cid).unwrap_or_default())
                        .clone();
                    for &f in &from_files {
                        for &t in &to_files {
                            pairs.push((f, t));
                        }
                    }
                }
                ConstraintKind::ForbiddenDep { from, to } => {
                    let from_pat = Pattern::new(from).map_err(|e|
                        SutraError::Internal(format!("invalid glob from='{}': {e}", from)))?;
                    let to_pat = Pattern::new(to).map_err(|e|
                        SutraError::Internal(format!("invalid glob to='{}': {e}", to)))?;
                    let from_files: Vec<i64> = path_map.iter()
                        .filter(|(_, p)| from_pat.matches_with(p, glob_opts))
                        .map(|(&id, _)| id)
                        .collect();
                    for &fid in &from_files {
                        for (&tid, tpath) in path_map {
                            if to_pat.matches_with(tpath, glob_opts) {
                                pairs.push((fid, tid));
                            }
                        }
                    }
                }
                _ => {} // MaxFanIn, NoCycles not expressed as forbidden pairs
            }
        }

        pairs.sort();
        pairs.dedup();

        // 3. Cache
        self.cache = Some(ResolvedCache {
            pairs: pairs.clone(),
            membership_generation: current_gen,
        });

        Ok(pairs)
    }

    pub fn invalidate(&mut self) {
        self.cache = None;
    }
}

fn find_component(
    components: &[crate::db::ComponentRow],
    name_or_id: &str,
) -> Option<String> {
    components.iter()
        .find(|c| c.name == name_or_id || c.id == name_or_id)
        .map(|c| c.id.clone())
}
```

### Step 3: Write integration tests

Test file: `tests/resolver-test.rs`. Uses `Db::open_unchecked` with tempdir and manual component/membership setup.

Test cases:
1. **boundary_resolution_with_membership** — create two components with known file memberships, add a boundary constraint, assert correct cross-product pairs
2. **cache_hit_on_unchanged_membership** — resolve twice without changing membership, verify second call returns same result (can verify by checking that the pairs match without re-querying — behavior test)
3. **cache_miss_on_membership_change** — resolve, then rerun clustering (update clustering_meta), resolve again, verify re-resolution produces updated pairs
4. **forbidden_dep_passes_through** — ForbiddenDep constraint with glob patterns, no component involvement, assert correct glob-matched pairs
5. **mixed_boundary_and_forbidden_dep** — both constraint types in one resolve call, verify combined + deduped output
6. **unknown_component_skipped** — boundary constraint referencing nonexistent component, verify it's skipped (no error, no pairs from it)
7. **empty_constraints** — resolve with no constraints returns empty vec

